import { useState, useEffect, useCallback } from 'react';

/**
 * Хук для управления аутентификацией пользователя
 * Обрабатывает вход, регистрацию, выход и обновление токенов
 */
export const useAuth = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [csrfToken, setCsrfToken] = useState(null);

  // Обновление токена доступа
  const refreshAccessToken = async () => {
    try {
      const token = localStorage.getItem('token');
      if (!token) return null;

      const response = await fetch(
        'http://localhost/api/accounts/users/me/',
        {
          method: 'GET',
          headers: {
            Authorization: `Token ${token}`
          },
          credentials: 'include'
        }
      );

      if (response.ok) {
        return token;
      } else {
        localStorage.removeItem('token');
        setIsLoggedIn(false);
        setUser(null);
        return null;
      }
    } catch (error) {
      console.error('Ошибка обновления токена:', error);
      return null;
    }
  };

  // Выполнение запросов с аутентификацией
  const fetchWithAuth = async (url, options = {}) => {
    let token = localStorage.getItem('token');

    const makeRequest = async (authToken) => fetch(url, {
        ...options,
        headers: {
          ...options.headers,
          Authorization: `Token ${authToken}`,
          'Content-Type': 'application/json'
        },
        credentials: 'include'
      });

    let response = await makeRequest(token);

    if (response.status === 401) {
      token = await refreshAccessToken();
      if (token) {
        response = await makeRequest(token);
      }
    }

    return response;
  };

  // Получение профиля пользователя
  const fetchUserProfile = useCallback(async () => {
    try {
      const response = await fetchWithAuth(
        'http://localhost/api/accounts/users/me/'
      );

      if (response.ok) {
        const data = await response.json();
        setUser(data);
        setIsLoggedIn(true);
      } else {
        localStorage.removeItem('token');
        setIsLoggedIn(false);
        setUser(null);
      }
    } catch (error) {
      console.error('Ошибка получения профиля:', error);
      localStorage.removeItem('token');
      setIsLoggedIn(false);
      setUser(null);
    }
  }, []);

  // Инициализация аутентификации
  useEffect(() => {
    const initializeAuth = async () => {
      try {
        // Получаем CSRF токен из cookie
        const cookies = document.cookie.split(';');
        for (const cookie of cookies) {
          const [name, value] = cookie.trim().split('=');
          if (name === 'csrftoken') {
            setCsrfToken(value);
            break;
          }
        }

        // Проверяем токен доступа
        const token = localStorage.getItem('token');
        if (token) {
          await fetchUserProfile();
        }
      } catch (error) {
        console.error('Ошибка инициализации:', error);
      } finally {
        setLoading(false);
      }
    };

    initializeAuth();
  }, [fetchUserProfile]);

  // Обработка входа
  const handleLogin = async (loginData) => {
    try {
      const response = await fetch(
        'http://localhost/api/accounts/users/login/',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(csrfToken ? { 'X-CSRFToken': csrfToken } : {})
          },
          credentials: 'include',
          body: JSON.stringify(loginData)
        }
      );

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem('token', data.token);
        setUser(data.user);
        setIsLoggedIn(true);
      } else {
        throw new Error(data.detail || data.message || 'Ошибка входа');
      }
    } catch (error) {
      throw error;
    }
  };

  // Обработка регистрации
  const handleRegister = async (registrationData) => {
    try {
      const response = await fetch(
        'http://localhost/api/accounts/users/',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(csrfToken ? { 'X-CSRFToken': csrfToken } : {})
          },
          credentials: 'include',
          body: JSON.stringify(registrationData)
        }
      );

      const data = await response.json();

      if (response.ok) {
        // Если есть pending_registration_id, значит нужна Telegram-верификация
        if (data.pending_registration_id) {
          return {
            success: true,
            needsTelegramVerification: true,
            pending_registration_id: data.pending_registration_id,
            // Для обратной совместимости с компонентами
            verification_id: data.pending_registration_id,
            user: data.user
          };
        }
        
        // Обычная регистрация без Telegram-верификации
        localStorage.setItem('token', data.token);
        setUser(data.user);
        setIsLoggedIn(true);
        return {
          success: true,
          needsTelegramVerification: false
        };
      } else {
        const error = new Error(
          data.detail || data.message || 'Ошибка регистрации'
        );
        error.response = { data };
        throw error;
      }
    } catch (error) {
      throw error;
    }
  };

  // Обработка выхода
  const handleLogout = async () => {
    try {
      await fetch('http://localhost/api/accounts/users/logout/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(csrfToken ? { 'X-CSRFToken': csrfToken } : {}),
          Authorization: `Token ${localStorage.getItem('token')}`
        },
        credentials: 'include'
      });
    } catch (error) {
      console.error('Ошибка при выходе из системы:', error);
    } finally {
      localStorage.removeItem('token');
      setIsLoggedIn(false);
      setUser(null);
    }
  };

  // Активация Telegram-бота
  const activateTelegramBot = async (verificationId, telegramChatId) => {
    try {
      const response = await fetch(
        'http://localhost/api/accounts/telegram/activate/',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(csrfToken ? { 'X-CSRFToken': csrfToken } : {})
          },
          credentials: 'include',
          body: JSON.stringify({
            verification_id: verificationId,
            telegram_chat_id: telegramChatId
          })
        }
      );

      const data = await response.json();

      if (response.ok) {
        return { success: true, data };
      } else {
        throw new Error(data.detail || data.message || 'Ошибка активации бота');
      }
    } catch (error) {
      throw error;
    }
  };

  // Верификация Telegram-кода
  const verifyTelegramCode = async (verificationId, code) => {
    try {
      const response = await fetch(
        'http://localhost/api/accounts/telegram/verify/',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(csrfToken ? { 'X-CSRFToken': csrfToken } : {})
          },
          credentials: 'include',
          body: JSON.stringify({
            verification_id: verificationId,
            code
          })
        }
      );

      const data = await response.json();

      if (response.ok) {
        // После успешной верификации устанавливаем пользователя как авторизованного
        localStorage.setItem('token', data.token);
        setUser(data.user);
        setIsLoggedIn(true);
        return { success: true, data };
      } else {
        throw new Error(data.detail || data.message || 'Ошибка верификации кода');
      }
    } catch (error) {
      throw error;
    }
  };

  // Кастомная функция для установки пользователя с обновлением состояния входа
  const setUserWithLogin = (userData) => {
    setUser(userData);
    setIsLoggedIn(!!userData); // true если userData не null/undefined
  };

  return {
    user,
    setUser: setUserWithLogin,
    loading,
    isLoggedIn,
    login: handleLogin,
    register: handleRegister,
    logout: handleLogout,
    fetchUserProfile,
    apiRequest: fetchWithAuth,
    activateTelegramBot,
    verifyTelegramCode
  };
};